import QtQuick 2.0
import QtComponents 1.3

Rectangle {
    width: 640
    height: 480
    color: "white"

    Text {
        text: "Network scan result analysis"
        font: new QFont("Arial", 14)
        anchors.centerIn: this
    }

    Container {
        width: 640
        height: 540

        Text {
            text: "IP address: `127.0.0.1`"
            font: new QFont("Arial", 14)
            anchor: TextAnchor.MiddleRight
        }

        Line {
            x: 360
            y: height - 240
            width: 180
            height: 5
            color: "black"
            stroke-width: 2
            lineDash: Array(2, 3)
            opacity: 0.5

            Rectangle {
                anchors.bottom: this.bottomAnchor
                fill: "white"
                radius: 40
                cursor: "pointer"

                onClicked: {
                    copilot.anomalyDetectionCheck()
                }
            }

        Button {
            text: "Anomaly detection check"
            width: 180
            height: 50
            color: "black"
            font: new QFont("Arial", 12)

            onClicked: {
                copilot.anomalyDetectionCheck()
            }

            Tooltip {
                anchors.centerIn: this

                description: "Identify any anomalies in the network scan result."
            }
        }
    }
}
